    if (dates.length === 1) {
      // If no dateFormat is specified, return the date string as is (which is in ISO format from storage)
      if (this._config.dateFormat === null) {
        return dates[0]
      }
      return this._formatDate(dates[0])
    }

    // For date ranges, use en-dash; for multiple dates, use comma
    const separator = this._config.selectionMode === 'multiple-ranged' ? ' – ' : ', '
    if (this._config.dateFormat === null) {
      return dates.join(separator)
    }
